 run:function(){
   var g,p,bad=[],oBoss=bossTick,oWater=inWater,nk=Object.assign({},NET),oldKit=CFG.raiderKit,i,e;
   function ok(v,s){if(!v) bad.push(s);}
   function bot(n,h){
