       e.rushT=0.01; updateEnts(0.02); ok(e.rushT===0&&e.cornered&&e.state!=='extract','rush expiration restarted escape');
     }
     fragProbe(0,0,true); fragProbe(1,0,true); fragProbe(1,1,true); fragProbe(0,0,false);
